W.day({ start: 9, ground: '#7c8a55', zoom: 0.62 });
S.waterMat = (c, o = 0.86) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.08, metalness: 0.25, transparent: true, opacity: o });
